function renderLinkedContentEffects(d){
 const taskIds=new Set(d.tasks.filter(t=>t.storeId===d.store.id).map(t=>t.id));
 const list=(d.effects.contents||[]).filter(v=>taskIds.has(v.taskId)&&(!v.storeId||v.storeId===d.store.id));
 const rows=list.map(v=>'<div class="list-item"><div><strong>'+esc(v.title||"未命名作品")+'</strong><div class="meta">'+esc(v.platform)+' · '+esc(v.taskTitle||v.taskId)+'</div><div class="meta">数据来源：'+esc(v.metricSource||"未采集")+' · 最近同步：'+esc(v.lastSyncedAt||"尚未同步")+'</div></div>'+pill(v.attributionStatus)+'</div>').join("");
 return '<section class="card mb"><div class="card-head"><h3>本系统发布内容与表现</h3>'+btn("账号运营监测","nav-account-ops")+'</div>'+(list.length?rows:'<div class="empty">尚无与营销任务关联的发布作品。完成发布后，请登记作品并核验归属。</div>')+'</section>';
}


function renderModal(title,body,submitLabel="保存"){return '<div class="modal-backdrop" id="modal"><div class="modal"><div class="row between mb"><h2>'+title+'</h2><button class="btn" data-action="close-modal">关闭</button></div>'+body+'</div></div>'}
function showModal(html){$("#modal-root")?.remove();document.body.insertAdjacentHTML("beforeend",'<div id="modal-root">'+html+'</div>')}

function table(heads,rows){return '<div class="table-wrap"><table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>'}
function modalForm(title,fields,submitAction,id=''){return renderModal(title,'<form id="modalForm" data-submit="'+submitAction+'" data-id="'+esc(id)+'">'+fields+'<div class="actions mt"><button class="btn primary" type="submit">保存</button><button class="btn" type="button" data-action="close-modal">取消</button></div></form>')}
function storePath(kind){return ({product:"products",offer:"offers",knowledge:"knowledge",asset:"assets",channel:"channels"})[kind]}
function storeList(kind){const key=storePath(kind);return key?db()[key]:[]}
