if(a==='save-product'){o.price=Number(o.price||0);o.assetIds=Array.isArray(o.assetIds)?o.assetIds:String(o.assetIds||'').split(',').map(x=>x.trim()).filter(Boolean);const existing=id?storeList('product').find(p=>p.id===id):null,changed=!existing||Object.keys(o).some(k=>JSON.stringify(existing[k])!==JSON.stringify(o[k]));o.confirmed=existing&&!changed?existing.confirmed:false;o.confirmedAt=existing&&!changed?(existing.confirmedAt||''):'';o.confirmedBy=existing&&!changed?(existing.confirmedBy||''):'';id?update(storePath('product'),id,o):add(storePath('product'),o)}
